nta.declaration:
// MAP BOUNDARIES
const int MAX_X = 17; // The rightmost cell boundary.
const int MAX_Y = 12; // The topmost cell boundary (home bays).
const int MIN_X = 0; // The leftmost boundary.
const int MIN_Y = 0; // The bottommost boundary.

// INITIAL TIMEOUT
const int INITIAL_TIMEOUT = 300;

// FROG
int[0, MAX_X] frog_x = 9; // Frogger's current X position.
int[0, MAX_Y] frog_y = 0; // Frogger's current Y position.

// GAME PROGRESSION
int[0, 5] lives = 5; // The player starts with 5 lives.
int score = 0; // Total points scored.
int[0, 5] home_bays_filled = 0; // Tracks how many of the 5 bays are occupied.
bool bay_occupied[5]; // An array tracking which specific bays are filled (Indices 0 to 4 mapping to the 5 home bay pairs).

// CLOCK
clock game_timer; // Tracks the 30-second (or less) countdown.
clock time_since_respawn; // Tracks the 2 seconds (20 units) Frogger must wait before moving after dying or scoring.

// DANGER ZONES
bool danger[MAX_X + 1][MAX_Y + 1]; // Vehicles update their current footprint to true here. If Frogger is on a true tile, he dies.
bool safe_platform[MAX_X + 1][MAX_Y + 1]; // Logs and Turtles update their footprint here. If Frogger is in the river (Y = 7 to 11) and this is false, he drowns.

// CHANNELS
broadcast chan jump; // Triggered when Frogger decides to move.
broadcast chan die; // Triggered when Frogger touches a vehicle, submerging turtle, or drowns.
broadcast chan score_bay; // Triggered when Frogger lands in an empty home bay.
broadcast chan new_level; // Triggered when home_bays_filled == 5.

template.declaration:
clock c;
int current_x;

// Updates the danger map for the vehicle's footprint
void update_footprint(bool is_danger) {
    for (int i = 0; i < size; i++) {
        int px = current_x + i;
        // Only update if it is currently within the visible screen
        if (px >= 0 && px <= MAX_X) {
            danger[px][y_row] = is_danger;
        }
    }
}

void move() {
    update_footprint(false); // Clear old position

    if (y_row % 2 != 0) { 
        // Odd rows move Right to Left
        current_x--;
        // Reappear on the opposite side after 2 cell delay
        if (current_x < -2) {
            current_x = MAX_X;
        }
    } else { 
        // Even rows move Left to Right
        current_x++;
        if (current_x > MAX_X + 2) {
            current_x = -size; // Start sliding in from the left
        }
    }

    update_footprint(true);  // Draw new position
}

clock c;
int current_x;

// Updates the safe_platform map for the object's footprint
void update_footprint(bool is_safe) {
    for (int i = 0; i < size; i++) {
        int px = current_x + i;
        // Only update if it is currently within the visible screen
        if (px >= 0 && px <= MAX_X) {
            safe_platform[px][y_row] = is_safe;
        }
    }
}

void move() {
    // Check if Frogger is standing on this specific object BEFORE it moves
    bool carrying_frog = (frog_y == y_row && frog_x >= current_x && frog_x < current_x + size);

    update_footprint(false); // Clear old position

    // Move Left to Right (Rows 8, 9, 11)
    if (y_row == 8 || y_row == 9 || y_row == 11) {
        current_x++;

        // Object wrap-around
        if (current_x > MAX_X + 2) {
            current_x = -size; 
        }

        // Carry Frogger and handle his wrap-around
        if (carrying_frog) {
            frog_x++;
            if (frog_x > MAX_X) {
                frog_x = 0; 
            }
        }
    } 
    // Move Right to Left (Rows 7, 10)
    else { 
        current_x--;

        // Object wrap-around
        if (current_x < -2) {
            current_x = MAX_X;
        }

        // Carry Frogger and handle his wrap-around
        if (carrying_frog) {
            frog_x--;
            if (frog_x < 0) {
                frog_x = MAX_X; 
            }
        }
    }

    update_footprint(true);  // Draw new position
}

clock c;
clock timer;
int current_x;
bool submerged = false; // Tracks if the turtle is underwater

// Helper to check if Frogger is standing on THIS specific turtle
bool carrying_frog() {
    return (frog_y == y_row && frog_x >= current_x && frog_x < current_x + size);
}

void update_footprint(bool is_safe) {
    for (int i = 0; i < size; i++) {
        int px = current_x + i;
        if (px >= 0 && px <= MAX_X) {
            safe_platform[px][y_row] = is_safe;
        }
    }
}

void move() {
    bool has_frog = carrying_frog();
    update_footprint(false); // Clear old position

    // Diving turtles only exist on rows 7 and 10, which move Right to Left
    current_x--;
    if (current_x < -2) {
        current_x = MAX_X;
    }

    // Carry Frogger and wrap him around
    if (has_frog) {
        frog_x--;
        if (frog_x < 0) {
            frog_x = MAX_X;
        }
    }

    // Only draw the new footprint if the turtle is NOT currently submerged
    if (!submerged) {
        update_footprint(true);
    }
}

clock move_timer; // To enforce the 1-unit delay between moves
bool is_dead = false;

// Helper to check if Frogger is in a lethal situation
void check_safety() {
    // Hit by a vehicle
    if (danger[frog_x][frog_y]) {
        is_dead = true;
    }
    // Drowning in the river (Rows 7-11)
    if (frog_y >= 7 && frog_y <= 11 && !safe_platform[frog_x][frog_y]) {
        is_dead = true;
    }
    // Game timeout (30 seconds = 300 units)
    if (game_timer >= INITIAL_TIMEOUT) {
        is_dead = true;
    }
}


// Checks if the X coordinate corresponds to a home bay and if it is free
bool is_valid_bay(int x) {
    // Check if X is within one of the 5 specific bay ranges
    if (x >= 0 && x <= 1) return !bay_occupied[0];
    if (x >= 4 && x <= 5) return !bay_occupied[1];
    if (x >= 8 && x <= 9) return !bay_occupied[2];
    if (x >= 12 && x <= 13) return !bay_occupied[3];
    if (x >= 16 && x <= 17) return !bay_occupied[4];

    // If X is in a green "wall" area (2-3, 6-7, etc.), it's not a valid bay
    return false; 
}

void respawn() {
    frog_x = 9;
    frog_y = 0;
    is_dead = false;
    game_timer = 0;
    time_since_respawn = 0;
}

nta.system:
// Place template instantiations here.
Process = Template();
// List one or more processes to be composed into a system.
system Process;
